package com.smartcanteen.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="payments")
public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="order_id",nullable=false,unique=true) private CustomerOrder order; @Column(nullable=false,length=30) private String provider="RAZORPAY"; @Column(unique=true,length=100) private String providerOrderId; @Column(unique=true,length=100) private String providerPaymentId; @Column(nullable=false,precision=10,scale=2) private BigDecimal amount; @Column(nullable=false,length=3) private String currency="INR"; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PaymentStatus paymentStatus=PaymentStatus.CREATED; @Column(nullable=false) private boolean signatureVerified=false; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); @PreUpdate void touch(){updatedAt=Instant.now();} public Long getId(){return id;} public CustomerOrder getOrder(){return order;} public void setOrder(CustomerOrder v){order=v;} public String getProviderOrderId(){return providerOrderId;} public void setProviderOrderId(String v){providerOrderId=v;} public String getProviderPaymentId(){return providerPaymentId;} public void setProviderPaymentId(String v){providerPaymentId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public PaymentStatus getPaymentStatus(){return paymentStatus;} public void setPaymentStatus(PaymentStatus v){paymentStatus=v;} public boolean isSignatureVerified(){return signatureVerified;} public void setSignatureVerified(boolean v){signatureVerified=v;} }
